import ast, difflib, io, subprocess


def head(path):
    return subprocess.run(
        ["git", "show", "HEAD:" + path], capture_output=True, check=True
    ).stdout.decode("utf-8")


def import_region(text):
    tree = ast.parse(text)
    lines = text.splitlines(keepends=True)
    first = None
    last = None
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            if first is None:
                first = node.lineno
            last = node.end_lineno
        elif first is not None:
            break
    return "".join(lines[first - 1 : last])


def docstring(text):
    tree = ast.parse(text)
    node = tree.body[0].value
    lines = text.splitlines(keepends=True)
    return "".join(lines[node.lineno - 1 : node.end_lineno])


for path, anchor in (
    ("mlx_lm/models/deepseek_v41.py", "class Model(nn.Module):"),
    ("tests/test_deepseek_v41.py", None),
):
    base = head(path)
    cur = io.open(path, encoding="utf-8").read()
    if anchor:
        a = cur[cur.index(anchor) :]
        b = base[base.index(anchor) :]
        print(path, "model-region diff:")
        for line in difflib.unified_diff(
            b.splitlines(), a.splitlines(), lineterm="", n=1
        ):
            print("   ", line)
    print(path, "import region base/cur equal:", import_region(base) == import_region(cur))
    print(path, "docstring base/cur equal:", docstring(base) == docstring(cur))
